def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Find the three-cell template, either horizontal or vertical.
    template = None
    for dr, dc in ((0, 1), (1, 0)):
        for r in range(h - 2 * dr):
            for c in range(w - 2 * dc):
                vals = [grid[r + i * dr][c + i * dc] for i in range(3)]
                if all(v != bg for v in vals) and len(set(vals)) > 1:
                    template = (r, c, dr, dc, vals)
                    break
            if template:
                break
        if template:
            break

    if template is None:
        return [row[:] for row in grid]

    r0, c0, dr, dc, vals = template
    template_colors = set(vals)
    candidates = [v for v in counts if v != bg and v not in template_colors]
    if not candidates:
        return [row[:] for row in grid]
    marker = max(candidates, key=lambda v: counts[v])

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, value in enumerate(vals):
                    rr = r + (i - 1) * dr
                    cc = c + (i - 1) * dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out
